CREATE TABLE metadata_record_values (tenant_id BIGINT UNSIGNED NOT NULL,record_type VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,record_id BIGINT UNSIGNED NOT NULL,field_key VARCHAR(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,field_type VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,schema_version BIGINT UNSIGNED NOT NULL,value_text VARCHAR(4000) NULL,value_long MEDIUMTEXT NULL,value_integer BIGINT NULL,value_decimal DECIMAL(26,6) NULL,value_boolean BOOLEAN NULL,value_date DATE NULL,value_datetime DATETIME(6) NULL,value_json JSON NULL,value_reference_id BIGINT UNSIGNED NULL,value_hash BINARY(32) NULL,updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(tenant_id,record_type,record_id,field_key),UNIQUE KEY metadata_custom_unique(tenant_id,record_type,field_key,value_hash),KEY metadata_custom_text(tenant_id,record_type,field_key,value_text(100),record_id),KEY metadata_custom_integer(tenant_id,record_type,field_key,value_integer,record_id),KEY metadata_custom_decimal(tenant_id,record_type,field_key,value_decimal,record_id),KEY metadata_custom_boolean(tenant_id,record_type,field_key,value_boolean,record_id),KEY metadata_custom_date(tenant_id,record_type,field_key,value_date,record_id),KEY metadata_custom_datetime(tenant_id,record_type,field_key,value_datetime,record_id),KEY metadata_custom_reference(tenant_id,record_type,field_key,value_reference_id,record_id),CONSTRAINT metadata_value_type CHECK(field_type IN('TEXT','LONG_TEXT','BOOLEAN','INTEGER','DECIMAL','DATE','DATETIME','CHOICE','MULTI_CHOICE','REFERENCE')),CONSTRAINT fk_metadata_value_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
